-- =====================================================================================
-- 02_DML.sql  |  Datos de prueba  |  Action Sport Club - reservas de canchas
-- Ejecutar después de 01_DDL.sql, conectado como RESERVAS ("Ejecutar script", F5).
-- Orden: dimensiones -> hechos -> COMMIT -> sincronización de IDENTITY -> verificación.
--
-- Fecha de corte de los datos: 11/11/2026, 09:00 (hora de Bogotá).
--   * Historial desde el 03/08/2026; reservas futuras hasta el 29/11/2026.
--   * Ninguna reserva se creó después del corte ni después de su hora de inicio.
--   * Las reservas que iniciaron antes del corte están PAGADA, VENCIDA o CANCELADA.
--   * Solo las reservas PAGADA y ya terminadas tienen calificación.
--   * Ninguna reserva activa se cruza con otra de la misma cancha (incluye 2 y 3 horas).
--   * Usuarios BLOQUEADO e INACTIVO: sin reservas posteriores al corte.
--   * Vóley Arena 2 (El Escobero) en mantenimiento desde el 04/11/2026: sin reservas desde esa fecha.
--   * Pádel 3 (San Lucas) cerrada desde el 01/10/2026: sin reservas desde esa fecha.
-- Usuarios ficticios; sedes y deportes reales del club. Precios de referencia.
-- =====================================================================================

----------------------------------- 1. DIM_USUARIO (80 filas) ---------------------------

----------------------------------- 2. DIM_CANCHA (15 filas) ----------------------------

----------------------------------- 3. DIM_TIEMPO (3856 filas) --------------------------
-- Bloques de una hora (06:00 a 21:00) del 03/08/2026 al 31/03/2027.
-- id_tiempo = (fecha - 03/08/2026) * 16 + (hora_inicio - 5)
-- Para ampliar el calendario basta con mover la fecha final: los id existentes no cambian.
-- El día de la semana se calcula con aritmética de fechas (el 03/01/2000 fue lunes).
-- Festivos de Colombia en el rango (Ley Emiliani aplicada).
SELECT d.n * 16 + (h.n - 5),
       d.fecha,
       h.n,
       EXTRACT(YEAR  FROM d.fecha),
       EXTRACT(MONTH FROM d.fecha),
       CASE MOD(d.fecha - DATE '2000-01-03', 7)
            WHEN 0 THEN 'LUNES'  WHEN 1 THEN 'MARTES'  WHEN 2 THEN 'MIERCOLES'
            WHEN 3 THEN 'JUEVES' WHEN 4 THEN 'VIERNES' WHEN 5 THEN 'SABADO'
            ELSE 'DOMINGO' END,
       CASE WHEN h.n < 12 THEN 'MANANA' WHEN h.n < 18 THEN 'TARDE' ELSE 'NOCHE' END,
       CASE WHEN d.fecha IN (DATE '2026-08-07',   -- Batalla de Boyacá
                             DATE '2026-08-17',   -- Asunción de la Virgen
                             DATE '2026-10-12',   -- Día de la Raza
                             DATE '2026-11-02',   -- Todos los Santos
                             DATE '2026-11-16',   -- Independencia de Cartagena
                             DATE '2026-12-08',   -- Inmaculada Concepción
                             DATE '2026-12-25',   -- Navidad
                             DATE '2027-01-01',   -- Año Nuevo
                             DATE '2027-01-11',   -- Reyes Magos
                             DATE '2027-03-22',   -- San José
                             DATE '2027-03-25',   -- Jueves Santo
                             DATE '2027-03-26')   -- Viernes Santo
            THEN 'SI' ELSE 'NO' END
FROM (SELECT LEVEL - 1 AS n, DATE '2026-08-03' + LEVEL - 1 AS fecha
      FROM dual
      CONNECT BY LEVEL <= DATE '2027-03-31' - DATE '2026-08-03' + 1) d
CROSS JOIN (SELECT LEVEL + 5 AS n FROM dual CONNECT BY LEVEL <= 16) h;

----------------------------------- 4. FACT_RESERVA (665 filas) ------------------------
-- valor_total = duracion_horas * precio_hora de la cancha.
-- id_tiempo = bloque de INICIO de la reserva.

COMMIT;

----------------------------------- 5. SINCRONIZAR IDENTITY ---------------------------
-- Los INSERT usaron id explícitos. START WITH LIMIT VALUE toma el id más alto de cada
-- tabla y continúa desde el siguiente, así la aplicación no choca con la PK.
ALTER TABLE dim_usuario  MODIFY (id_usuario GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE dim_cancha   MODIFY (id_cancha  GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE dim_tiempo   MODIFY (id_tiempo  GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE fact_reserva MODIFY (id_reserva GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));

----------------------------------- 6. VERIFICACIÓN -----------------------------------
-- Esperado: 80 usuarios, 15 canchas, 3.856 bloques y 665 reservas.
SELECT 'dim_usuario' AS tabla, COUNT(*) AS filas FROM dim_usuario
UNION ALL SELECT 'dim_cancha',   COUNT(*) FROM dim_cancha
UNION ALL SELECT 'dim_tiempo',   COUNT(*) FROM dim_tiempo
UNION ALL SELECT 'fact_reserva', COUNT(*) FROM fact_reserva;

SELECT estado_reserva, COUNT(*) AS reservas
FROM fact_reserva
GROUP BY estado_reserva
ORDER BY reservas DESC;

SELECT table_name, column_name, generation_type
FROM user_tab_identity_cols;
